const FACTS="TABAQ's four coordinated fragrance layering kits are Clean Skin, Soft Bloom, Amber Haze and Juice Drift. Each contains 50ml Layering Veil (Lift), 30ml Eau de Parfum (Define), 10ml Layering Essence 01 (Soften), 10ml Layering Essence 02 (Deepen), and 5ml Scent Balm. Each kit costs R1,750 in South Africa / USD 107 international product price before shipping. Standard South African delivery is free for 2+ kits; one-kit SA and international delivery quoted before payment. TABAQ is a fragrance house designed around layering and thoughtful quality. No independent global-first claim, performance hours, concentrations, raw material origins, certifications, exact stock, or delivery promises are supplied. Do not invent them.";
const normalize=s=>String(s||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g," ").trim();
const has=(q,w)=>(" "+q+" ").includes(" "+normalize(w)+" ");
function retrieve(q,limit=6){q=normalize(q);return KB.map((r,i)=>({r,i,s:r[1].split("|").reduce((n,w)=>n+(has(q,w)?(w.includes(" ")?4:1):0),0)})).filter(x=>x.s>0).sort((a,b)=>b.s-a.s||a.i-b.i).slice(0,limit).map(x=>x.r);}
function recommendation(q){q=normalize(q);let scores=Object.entries(PRODUCT).map(([id,p])=>({id,p,score:(has(q,p.name)?8:0)+p.words.split(" ").reduce((n,w)=>n+(has(q,w)?1:0),0)})).sort((a,b)=>b.score-a.score);return scores[0].score?scores[0]:null;}
/* REV239.3 — boutique voice, typo-tolerant intent, customer-safe reference rendering. */
function closeWord(a,b){if(a===b)return true;if(Math.abs(a.length-b.length)>1||a.length<3)return false;let i=0,j=0,d=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;continue;}if(++d>1)return false;if(a.length>b.length)i++;else if(b.length>a.length)j++;else{i++;j++;}}return d+(i<a.length||j<b.length?1:0)<=1;}
function brandMention(q){return q.split(" ").some(w=>w.length>=4&&closeWord(w,"tabaq"));}
function detailRequested(q){return /\b(in detail|technical detail|detailed|in depth|explain fully|step by step|scientific explanation|more detail|elaborate)\b/.test(normalize(q));}
function shortAnswer(text,max=55){text=String(text||"").trim().replace(/\s+/g," ");if(!text)return "";let words=text.split(" ");if(words.length<=max)return text;const sentences=text.match(/[^.!?]+[.!?]+(?:\s|$)|[^.!?]+$/g)||[];let out="";for(const sentence of sentences){const next=(out+" "+sentence.trim()).trim();if(next.split(/\s+/).length>max)break;out=next;}return out||words.slice(0,max-1).join(" ").replace(/[,;:]+$/,"")+"…";}
const BRAND_INTRO="At TABAQ, you don't simply wear a fragrance — you make it yours. Four beautifully coordinated layers, a little balm, and endless ways to play with your mood. Shall we find your signature?";
const MOOD="Tell me, are you more fresh and effortless, softly floral, warm and mysterious, or bright and playful?";
