const MASTER_LINKS=Object.freeze({support:{href:"/contact.html",label:"Contact the TABAQ team"},returns:{href:"/returns.html",label:"Read the returns policy"},privacy:{href:"/privacy.html",label:"Privacy & data requests"},shipping:{href:"/shipping.html",label:"Delivery information"},terms:{href:"/terms.html",label:"Company & terms"},shop:{href:"/#shop",label:"Explore current kits"},guide:{href:"/#layer-guide",label:"Explore the layering concept"},drop:{href:"/#drops",label:"View drop information"},access:{href:"/#waitlistForm",label:"Explore optional Drop Access"}});
