function technicalLevel(q){q=cleanQuery(q);return /\b(w w|v v|partition|partitioning|substantivity|diffusion|volatility|solubility|stereoisomer|enantiomer|gc ms|gc olfactometry|matrix|odor threshold|odour threshold|fragrance load|headspace|combined use|ifra category|technical|formulation|quantitative|molecular)\b/.test(q)?"specialist":/\b(accord|drydown|chypre|fougere|sillage|projection|longevity|extrait|notes|perfumery|olfactory|extract|attar)\b/.test(q)?"enthusiast":"everyday";}
