 if(/\b(reviews|testimonials|customer feedback|best seller|bestseller|popular|how many sold)\b/.test(q))return ans("I don’t have verified customer review or sales figures to quote. What I can help with is finding the scent direction that feels right for you.");
 if(/\b(sample|samples|sampling|try before|blind buy)\b/.test(q))return ans("Choosing fragrance without smelling it is always a little uncertain. I can help you compare the scent profiles, but our team can confirm whether a sampling option is available.","support");
 if(/\b(dupe|clone|better than|instead of|designer perfume|baccarat|sauvage|chanel|tom ford|creed|dior)\b/.test(q))return ans("A beautiful fragrance from another house can be a great choice. TABAQ's difference is the coordinated layering experience, rather than a promise to imitate another perfume. What part of that scent do you love most?");
