function masterAnswer(question,history=[],page="",commerce){
 const clean=cleanHistory(history),pre=masterPreflight(question,clean,page,commerce);if(pre)return pre;
 const p=masterContext(question,clean,page,commerce),q=cleanQuery(question);
 if(p.level==="specialist"&&/\b(w w|v v|concentration basis)\b/.test(q))return{reply:"Weight-by-weight is a mass fraction, while volume-by-volume is a volume fraction. Comparisons need the same basis and finished-product definition. An EDP label cannot establish an exact concentration."};
 if(p.dislikes.length&&!p.match&&/\b(hate|dislike|avoid|don t like|dont like|not for me)\b/.test(q))return{reply:"That's useful to know. I wouldn't push a fragrance built around a character you dislike. What scent direction do you enjoy instead?"};
 const result=salesAnswer(q,clean,page);
 // No purchase links for gated releases; product browsing can continue via the collection.
 if(result.action==="purchase")return{reply:"Please check the current product page for the latest price and availability.",link:"shop",locked:true};
 if(result.kit&&["SOLD_OUT","CLOSED","ARCHIVED","PRELAUNCH","COUNTDOWN","STALE"].includes(p.commerce.state))delete result.kit;
 if(result.kit&&p.gift)result.reply=result.reply.replace("I think it would suit you as a gift.","I think it could make a lovely gift.");
 return result;
}

